  aliasFor, cleanTools, judgeScreener, judgeSubmission, matchCriteria, parseCriteria, parseForm, parseLinks,
  parseScreener, readCriteria, screenerForEditing, snapshotOf, suitsModes, type ProfileFacts,
} from '../domain/eligibility.js'
