const profile: ProfileFacts = {
  job_family: 'it_ops',
  job_title: '서비스 운영',
  career: '6-9',
  industry: 'finance',
  company_size: 'large',
  tools: ['ServiceNow', 'Grafana'],
  modes: ['video', 'async'],
  regions: [],
  intro: '',
}

describe('company domains', () => {
  it('groups subdomains into one organisation', () => {
    expect(organisationDomain('mail.samsung.com')).toBe('samsung.com')
    expect(organisationDomain('research.lg.co.kr')).toBe('lg.co.kr')
    expect(organisationDomain('lg.co.kr')).toBe('lg.co.kr')
    expect(organisationDomain('Team.Example.COM.')).toBe('example.com')
  })
})

describe('criteria', () => {
  it('parses only known keys and keeps a company verification required by default', () => {
    const criteria = parseCriteria({ job_families: ['it_ops', 'dev', 'it_ops'], careers: ['6-9'], tools_any: ['servicenow', ' '] })
    expect(criteria.job_families).toEqual(['it_ops', 'dev'])
    expect(criteria.tools_any).toEqual(['ServiceNow'])
    expect(criteria.require_work).toBe(true)
    expect(() => parseCriteria({ job_families: ['astronaut'] })).toThrowError()
    expect(readCriteria({}).require_work).toBe(true)
    expect(readCriteria({ require_work: false }).require_work).toBe(false)
  })

  it('says, in words, which requirement is not met', () => {
    const open = parseCriteria({})
    expect(matchCriteria(profile, open, true)).toEqual({ ok: true, unmet: [] })
    expect(matchCriteria(profile, open, false).unmet).toEqual(['옆자리 회사 인증이 필요해요'])
    const narrow = parseCriteria({ job_families: ['dev'], careers: ['0-2'], tools_any: ['Datadog'], require_work: false })
    expect(matchCriteria(profile, narrow, false).unmet).toEqual([
      '찾는 직무가 달라요', '찾는 연차가 달라요', '찾는 도구 사용 경험이 없어요',
    ])
    expect(matchCriteria(profile, parseCriteria({ tools_any: ['grafana'] }), true).ok).toBe(true)
  })

  it('judges how a study runs against how the participant takes part', () => {
    expect(suitsModes(profile, 'async', 'online')).toBe(true)
    expect(suitsModes(profile, 'live', 'online')).toBe(true)
    expect(suitsModes(profile, 'live', 'in_person')).toBe(false)
    expect(suitsModes({ ...profile, modes: [] }, 'live', 'in_person')).toBe(true)
  })

  it('keeps tool names short, known ones in their usual spelling, no duplicates', () => {
    expect(cleanTools(['chatgpt', 'ChatGPT', 'x'.repeat(80), 3, '사내 시스템'])).toEqual(['ChatGPT', 'x'.repeat(40), '사내 시스템'])
  })
})

describe('screener', () => {
  const written = [
    {
      text: '업무에서 생성형 AI를 쓰나요?',
      kind: 'single',
      options: [{ label: '매일', disqualify: false }, { label: '가끔' }, { label: '안 써요', disqualify: true }],
    },
    { text: '주로 쓰는 도구', kind: 'multi', options: [{ label: 'ChatGPT' }, { label: 'Claude' }, { label: '기타' }] },
    { text: '어떤 일에 쓰는지 한 줄로', kind: 'text', required: false },
  ]

  it('splits what participants see from the rules that rule people out', () => {
    const { questions, rules } = parseScreener(written)
    expect(questions.map((q) => q.id)).toEqual(['q1', 'q2', 'q3'])
    expect(JSON.stringify(questions)).not.toContain('disqualify')
    expect(rules).toEqual({ q1: ['o3'] })
    // And back together for editing.
    const editing = screenerForEditing(questions, rules) as { options: { disqualify: boolean }[] }[]
    expect(editing[0]!.options.map((o) => o.disqualify)).toEqual([false, false, true])
  })

  it('refuses a screener nobody could pass, and a choice with one option', () => {
    expect(() => parseScreener([{ text: 'q', options: [{ label: 'a', disqualify: true }, { label: 'b', disqualify: true }] }])).toThrowError()
    expect(() => parseScreener([{ text: 'q', options: [{ label: 'only' }] }])).toThrowError()
    expect(() => parseScreener(new Array(11).fill({ text: 'q', kind: 'text' }))).toThrowError()
  })

  it('judges answers, keeping only known ones', () => {
    const { questions, rules } = parseScreener(written)
    const pass = judgeScreener(questions, rules, { q1: 'o1', q2: ['o1', 'o2', 'o2'], q3: '  문서 요약  ', extra: 'x' })
    expect(pass).toEqual({ eligible: true, answers: { q1: 'o1', q2: ['o1', 'o2'], q3: '문서 요약' } })
    expect(judgeScreener(questions, rules, { q1: 'o3', q2: ['o1'] }).eligible).toBe(false)
    expect(() => judgeScreener(questions, rules, { q1: 'o9', q2: ['o1'] })).toThrowError()
    expect(() => judgeScreener(questions, rules, { q2: ['o1'] })).toThrowError()
    // A prototype key is not an answer.
    expect(() => judgeScreener(questions, rules, JSON.parse('{"__proto__": {"q1": "o1"}, "q2": ["o1"]}'))).toThrowError()
  })
})

describe('submission form', () => {
  const form = parseForm([
    { text: '가장 불편했던 점', kind: 'long' },
    { text: '추천 의향', kind: 'rating' },
    { text: '화면 녹화 링크', kind: 'url', required: false },
    { text: '다시 쓰겠어요?', kind: 'choice', options: [{ label: '네' }, { label: '아니요' }] },
  ])

  it('checks every kind of answer', () => {
    expect(judgeSubmission(form, { f1: '검색이 느려요', f2: 4, f4: 'o1' })).toEqual({ f1: '검색이 느려요', f2: 4, f4: 'o1' })
    expect(() => judgeSubmission(form, { f1: 'x', f2: 6, f4: 'o1' })).toThrowError()
    expect(() => judgeSubmission(form, { f1: 'x', f2: 3, f3: 'javascript:alert(1)', f4: 'o1' })).toThrowError()
    expect(() => judgeSubmission(form, { f2: 3, f4: 'o1' })).toThrowError()
  })

  it('accepts only web links for the task', () => {
    expect(parseLinks([{ label: '시제품', url: 'https://figma.com/proto/x' }, { url: '' }])).toEqual([
      { label: '시제품', url: 'https://figma.com/proto/x' },
    ])
    expect(() => parseLinks([{ url: 'javascript:alert(1)' }])).toThrowError()
  })
})

describe('code names', () => {
  const key = new Uint8Array(32).fill(3)

  it('are stable per study and different across studies', async () => {
    const a1 = await aliasFor(key, 'study-a', 'account-1')
    expect(a1).toMatch(/^P-[0-9A-HJKMNP-TV-Z]{6}$/)
    expect(await aliasFor(key, 'study-a', 'account-1')).toBe(a1)
    expect(await aliasFor(key, 'study-b', 'account-1')).not.toBe(a1)
    expect(await aliasFor(key, 'study-a', 'account-2')).not.toBe(a1)
    expect(await aliasFor(key, 'study-a', 'account-1', 8)).toHaveLength(10)
  })

  it('snapshot carries the coarse facts and nothing that names the person', () => {
    const snapshot = snapshotOf(profile, true, 2)
    expect(Object.keys(snapshot).sort()).toEqual(
      ['company_size', 'completed', 'career', 'industry', 'intro', 'job_family', 'job_title', 'tools', 'work_verified'].sort(),
    )
  })
})

describe('studies', () => {
  const base: StudyRow = {
    id: 's', org_id: 'o', title: 't', summary: '', description: '', sponsor_label: 'B2B SaaS 스타트업', show_org: false,
    org_name: 'Acme', kind: 'interview', mode: 'live', location: 'online', place: '', duration_minutes: 60,
    reward_amount: 30000, target_count: 5, apply_deadline: null, criteria: {}, screener: [], status: 'recruiting',
    published_at: new Date(), closed_at: null, submitted_at: null, created_at: new Date(), updated_at: new Date(),
  }

  it('names the client only when the study says so', () => {
    expect(studyView(base).sponsor).toBe('B2B SaaS 스타트업')
    expect(studyView({ ...base, show_org: true }).sponsor).toBe('Acme')
    expect(studyView({ ...base, sponsor_label: '' }).sponsor).toBe('의뢰 기업 비공개')
  })

  it('is open only while recruiting and before the deadline', () => {
    expect(isOpen(base)).toBe(true)
    expect(isOpen({ ...base, apply_deadline: new Date(Date.now() - 1000) })).toBe(false)
    expect(isOpen({ ...base, status: 'in_progress' })).toBe(false)
  })

  it('tells a participant where they stand and what to do next', () => {
    const app = { status: 'selected', eligible: true, mode: 'live', scheduled_at: null, submitted_at: null, study_status: 'recruiting' }
    expect(participationStage(app).action).toBe('schedule')
    expect(participationStage({ ...app, mode: 'async' }).action).toBe('submit')
    expect(participationStage({ ...app, status: 'applied', eligible: false }).stage).toBe('screened_out')
    expect(participationStage({ ...app, scheduled_at: new Date(Date.now() + 3_600_000) }).stage).toBe('scheduled')
  })
})

