describe('write limits', () => {
  const hours = 3600
  const days = 24 * hours

  it('tells a person blocked for the day to come back at Korean midnight, not nine hours later', () => {
    // 01:00 on the 8th in Seoul: the day counter rolls over in 23 hours.
    expect(retryAfterSeconds('day', new Date('2026-10-07T16:00:00Z'))).toBe(23 * hours)
    // 11:00 on the 7th in Seoul: 13 hours left of that Korean day.
    expect(retryAfterSeconds('day', new Date('2026-10-07T02:00:00Z'))).toBe(13 * hours)
  })

  it('counts the monthly wait to the start of the next Korean month, across the year as well', () => {
    expect(retryAfterSeconds('month', new Date('2026-10-31T16:00:00Z'))).toBe(29 * days + 23 * hours)
    expect(retryAfterSeconds('month', new Date('2026-12-31T16:00:00Z'))).toBe(30 * days + 23 * hours)
  })

  it('leaves the per-minute wait alone', () => {
    expect(retryAfterSeconds('minute', new Date('2026-10-07T16:00:00.000Z'))).toBe(60)
    expect(retryAfterSeconds('minute', new Date('2026-10-07T16:00:40.500Z'))).toBe(20)
  })

  it('keeps the counter key exactly as the database already has it', () => {
    const at = new Date('2026-10-07T16:30:12.345Z')
    expect(windowStart('minute', at).toISOString()).toBe('2026-10-07T16:30:00.000Z')
    expect(windowStart('day', at).toISOString()).toBe('2026-10-08T00:00:00.000Z')
    expect(windowStart('month', at).toISOString()).toBe('2026-10-01T00:00:00.000Z')
    expect(windowStart('month', new Date('2026-12-31T16:00:00Z')).toISOString()).toBe('2027-01-01T00:00:00.000Z')
  })
})

