const eun = (label: string) => `${label}${koreanParticle(label, '은', '는')}`

export type Validator<T> = {
  /** Reads `value`, recording any problem under `path`. */
  run(value: unknown, path: string, errors: FieldErrors): T | undefined
  readonly optional?: boolean
}

type Shape = Record<string, Validator<unknown>>
type Infer<S extends Shape> = { [K in keyof S]: S[K] extends Validator<infer T> ? T : never }

/** Validate `input` against `shape`, throwing a single validation_failed error. */
export function parse<S extends Shape>(shape: S, input: unknown): Infer<S> {
  const errors: FieldErrors = {}
  const source = (typeof input === 'object' && input !== null ? input : {}) as Record<string, unknown>
  const out: Record<string, unknown> = {}
  for (const [key, validator] of Object.entries(shape)) {
    const result = validator.run(source[key], key, errors)
    if (result !== undefined) out[key] = result
  }
  if (Object.keys(errors).length > 0) throw invalid(errors)
  return out as Infer<S>
}

/** Validate a single value, e.g. a path or query parameter. */
export function parseOne<T>(validator: Validator<T>, value: unknown, path: string): T {
  const errors: FieldErrors = {}
  const result = validator.run(value, path, errors)
  if (Object.keys(errors).length > 0) throw invalid(errors)
  return result as T
}

function fail(errors: FieldErrors, path: string, message: string): undefined {
  if (!(path in errors)) errors[path] = message
  return undefined
